import * as F from './firebase.mjs';
import HanziWriter from 'hanzi-writer';
import {modules,makeLesson,lessonId} from './curriculum.mjs';
import {escapeHtml as e,checkPinyin,shuffled} from './core.mjs';
import * as audio from './audio.mjs';
import {speechFeedbackView} from './speech-view.mjs';
import {createSpeechPlayback} from './speech-playback.mjs';
import {authView,nameFields,authError} from './auth-view.mjs';
import {directoryRows,messageView,deletionView} from './people-view.mjs';
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',back:'M19 12H5m6-6-6 6 6 6',book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4zM12 6v15',pen:'m4 20 4-1L20 7l-3-3L5 16zM14 7l3 3',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0zM5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8',keyboard:'M3 5h18v14H3zM6 9h1m3 0h1m3 0h1m3 0h1M6 12h1m3 0h1m3 0h1m3 0h1M7 16h10',volume:'M3 9h4l5-5v16l-5-5H3zM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',play:'m8 4 12 8-12 8z',check:'m5 12 4 4L19 6',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M17 4a4 4 0 0 1 0 7m1 4a4 4 0 0 1 4 4v2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',plus:'M12 5v14M5 12h14',refresh:'M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0 1 13-3l2 3M4 16l2 3a8 8 0 0 0 13-3',chart:'M4 20V4m0 16h16M8 16v-5m5 5V7m5 9V3'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const btn=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const S={inbox:{},thread:null,peopleSearch:'',nextPeoplePage:null,authMode:'signin',profile:null,user:null,admin:false,owner:false,loaded:false,error:'',lessons:new Map(),settings:{},module:'beginner',week:1,adminTab:'curriculum',draft:null,dirty:false,practice:null,attempts:[],members:[],admins:new Set(),rosterLoaded:false,preview:false};
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let stopInbox,toastTimer,writer,strokeData,writerSize=318,drawGeneration=0,authGeneration=0;
const adminPage=/\/admin\/?$/.test(location.pathname);
const modelUrls=new Map();
const playback=createSpeechPlayback({getModel:loadModelAudio,synthesis:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,status:text=>{const el=document.querySelector('#comparison-status');if(el)el.textContent=text;}});
async function loadModelAudio(){
 const p=S.practice,index=p.index,take=p.speechTake,w=p.words[index];
 if(S.preview)throw Error('Publish the lesson before requesting a server pronunciation example.');
 if(S.settings.speechProvider!=='openai')throw Error('No device Mandarin voice is available. Connect OpenAI in Settings for a spoken example, or follow the pinyin guide.');
 const key=JSON.stringify([p.lesson.moduleId,p.lesson.week,w.id,w.hanzi,w.pinyin]);let url=modelUrls.get(key);
 if(!url){const result=await F.api({action:'pronunciation',lessonId:lessonId(p.lesson.moduleId,p.lesson.week),wordId:w.id});if(S.practice!==p||p.index!==index||p.mode!=='speaking'||p.speechTake!==take)return null;
 const bytes=Uint8Array.from(atob(result.audio),c=>c.charCodeAt(0));url=URL.createObjectURL(new Blob([bytes],{type:result.mime}));modelUrls.set(key,url);}
 const container=document.querySelector('#model-audio-output');if(!container)return null;
 container.innerHTML=`<audio class="audio-player" controls src="${e(url)}" aria-label="Correct Mandarin pronunciation, AI-generated voice"></audio><p class="small muted">AI-generated Mandarin example. Follow the pinyin and your lecturer’s guidance.</p>`;
 return container.querySelector('audio');
}
function stopPlayback(){playback.stop();document.querySelectorAll('audio').forEach(a=>a.pause());}
function resetVoice(){stopPlayback();audio.disposeRecording();if(S.practice){S.practice.speechTake=(S.practice.speechTake||0)+1;S.practice.recordingUrl=null;S.practice.speechResult=null;}}
function currentSpeech(p,index,take,request){return S.practice===p&&p.index===index&&p.mode==='speaking'&&p.speechTake===take&&(request===undefined||p.feedbackRequest===request);}

function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),6000);}
function message(error){const code=error?.code||'';if(code.startsWith('auth/'))return authError(error);if(code.includes('popup-closed'))return 'Sign-in was cancelled. You can try again.';if(code.includes('popup-blocked'))return 'Allow the Google sign-in pop-up for this site, then try again.';if(code.includes('invalid-credential')||code.includes('wrong-password'))return 'The username or password is incorrect.';if(code.includes('network'))return 'The connection was interrupted. Check your internet connection and try again.';return String(error?.message||'Something went wrong. Please try again.').replace(/^Firebase:\s*/,'').replace(/\s*\(auth\/[^)]+\)\.?$/,'');}
async function run(fn,button){if(button)button.disabled=true;try{return await fn();}catch(error){toast(message(error));return null;}finally{if(button?.isConnected)button.disabled=false;}}
function modal(html){dialog.classList.remove('auth-dialog','message-modal');dialog.removeAttribute('aria-labelledby');dialog.innerHTML=`<button class="close" data-action="close-dialog" aria-label="Close dialog">×</button>${html}`;if(!dialog.open)dialog.showModal();}
function authModal(mode='signin'){S.authMode=mode;modal(authView(mode));dialog.classList.add('auth-dialog');dialog.setAttribute('aria-labelledby','auth-title');}
function showAuth(mode='signin'){S.authMode=mode;if(adminPage&&!S.user&&!dialog.open)render();else authModal(mode);}
function accountModal(){modal(`<h2>${e(S.user.displayName||'Your account')}</h2><p>${e(S.user.email)}</p><p>Your current module: ${e(modules.find(m=>m.id===S.module).name)}</p><div class="row account-actions"><a class="btn" href="/chinese/admin/">Teaching space ${icon('arrow')}</a>${btn('Edit my name','edit-profile','text')}${btn('Messages','my-messages','text')}${btn('Sign out','logout','text')}</div> ${S.user.uid!=='shared-teacher'?`<label class="notification-choice"><input type="checkbox" id="email-notifications" ${S.profile?.emailNotifications===false?'':'checked'}> Email me when my teaching team sends a message</label><p class="small muted">Notifications contain a link to your private conversation. You can turn them off here.</p>`:''} ${S.user.uid!=='shared-teacher'?`<div class="account-danger">${btn('Delete my account','delete-self','text danger-text')}</div>`:''}`);}
function profileModal(){const parts=(S.user?.displayName||'').trim().split(/\s+/);modal(`<h2>A name to make it yours.</h2><p>Confirm your first and last names so your lecturer can recognise your practice.</p><form id="profile-form" class="form-stack">${nameFields(S.profile?.firstName||parts[0]||'',S.profile?.lastName||parts.slice(1).join(' '))}<p class="auth-error" role="alert" hidden></p><button type="submit" class="btn primary wide">Save my name</button></form>`);}
function bindInbox(){stopInbox?.();stopInbox=null;if(S.user&&canPractise())stopInbox=F.watchInbox(S.user.uid,data=>{S.inbox={lastAdminSeq:0,userReadSeq:0,...data};const dot=document.querySelector('.inbox-button .unread-dot');if(dot)dot.hidden=!(S.inbox.lastAdminSeq>S.inbox.userReadSeq);});}
function canPractise(){return !!S.user&&(S.user.emailVerified||(S.user.uid==='shared-teacher'&&S.admin));}
function verificationModal(){modal(`<span class="auth-emblem" aria-hidden="true">信</span><h2>One last step. Check your inbox.</h2><p>We sent a verification link to <strong>${e(S.user.email)}</strong>. Open it to unlock your practice, then come back here.</p><div class="form-stack">${btn('I’ve verified my email','check-verification','primary wide')}${btn('Resend verification email','resend-verification','wide')}</div><p class="small muted">Check your spam folder too. Verification is required before you can practise.</p>`);}
function verificationBanner(){return S.user&&!S.user.emailVerified&&S.user.uid!=='shared-teacher'?`<div class="verification-banner" role="status"><div><strong>Verify your email</strong><span>Open the link in your inbox to unlock all practice, including AI speech feedback.</span></div><div class="row">${btn('Resend email','resend-verification','small')}${btn('I’ve verified','check-verification','small')}</div></div>`:'';}
function footer(){return `<footer class="footer"><span>Chinese Practice · A SATLE teaching prototype<br>Developed with Lucy Liu & Ivan Kulik</span><span><a href="#privacy" data-action="privacy">Privacy & practice data</a><br>少量练习，每天进步 · A little progress, every day.</span></footer>`;}
function header(){return `<header class="topbar"><a class="brand" href="/chinese/"><span class="brand-mark">中</span><span><strong>Chinese Practice</strong><small>Learn. Try. Grow.</small></span></a><nav class="topnav" aria-label="Main navigation"><a class="nav-secondary" href="/chinese/" ${!adminPage?'aria-current="page"':''}>My learning</a><a class="nav-secondary" href="/chinese/admin/" ${adminPage?'aria-current="page"':''}>Teaching space</a>${S.user?`${btn(`Messages <span class="unread-dot" ${!(S.inbox.lastAdminSeq>S.inbox.userReadSeq)?'hidden':''} aria-label="Unread messages"></span>`,'my-messages','small inbox-button')}${btn(`<span class="avatar">${e((S.user.displayName||'U').slice(0,1))}</span><span>${e((S.user.displayName||'Account').split(' ')[0])}</span>`,'account','small',`aria-label="Your account: ${e(S.user.displayName||'Your account')}"`)}`:`${btn('Sign in','sign-in','small auth-nav-signin')}${btn('Register','register','primary small')}`}</nav></header>`;}
function render(){
 if(S.practice&&!canPractise()){resetVoice();S.practice=null;S.preview=false;}
 drawGeneration++;writer?.cancelQuiz();
 app.innerHTML=header()+`<main id="main" class="shell">${verificationBanner()}${S.error?`<div class="notice" role="alert">${e(S.error)} ${btn('Retry connection','reload','small')}</div>`:''}${adminPage?(S.admin?(S.practice?practiceView():adminView()):loginView()):S.practice?practiceView():location.hash==='#privacy'?privacyView():location.hash.startsWith('#module=')?moduleView():homeView()}${footer()}</main>`;
 if(S.practice&&S.practice.mode==='writing')setupWriter();
 if(adminPage&&S.admin&&S.adminTab==='settings'&&!S.settings.backendReady){
  const panel=document.querySelector('.admin-main');panel?.insertAdjacentHTML('afterbegin','<div class="notice">AI connections and the shared password will become available after the project’s billing setup is activated. Weekly editing and Google sign-in are ready now.</div>');
  document.querySelectorAll('#provider-form input,#provider-form select,#provider-form button,#shared-form input,#shared-form button,#active-provider').forEach(el=>el.disabled=true);
 }
 if(adminPage&&!S.admin&&!S.settings.sharedLoginEnabled){const form=document.querySelector('#login-form');if(form){form.querySelectorAll('input,button').forEach(el=>el.disabled=true);form.insertAdjacentHTML('beforeend','<p class="small muted">The shared login has not been enabled yet. Please use Google sign-in.</p>');}}
}
function homeView(){return `<section class="hero"><div><span class="green-label"><span class="dot"></span>Your space to practise Chinese</span><h1>A little practice.<br><em>A lot more confidence.</em></h1><p>Listen closely. Find your strokes. Try again.<br>Small steps, shaped around what you’re learning with Lucy.</p><div class="hero-actions">${btn(`Start practising ${icon('arrow')}`,'start','primary')}<span class="small muted">At your pace. Every week.</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="paper-character"><span>学</span></div><div class="stamp">学习</div><div class="art-note"><strong>xué · to learn</strong>Every stroke is a new beginning.</div></div></section><div class="section-title"><h2>Choose your learning path</h2><p>12 weeks · Guided by your lecturer</p></div><section class="courses" aria-label="Learning pathways"><article class="course-card"><span class="level">BEGINNER · HSK 1</span><span class="course-symbol" aria-hidden="true">初</span><h3>Chinese foundations</h3><p>Start with the essentials. Build your vocabulary, pronunciation and character writing.</p><div class="card-footer"><span class="meta">${available('beginner')} week${available('beginner')===1?'':'s'} available</span>${btn(`Explore module ${icon('arrow')}`,'choose-module','small','data-module="beginner"')}</div></article><article class="course-card advanced"><span class="level">ADVANCED · HSK 4–5</span><span class="course-symbol" aria-hidden="true">商</span><h3>Chinese in context</h3><p>Develop your voice through business vocabulary and more confident expression.</p><div class="card-footer"><span class="meta">Business Chinese · HSK 5</span>${btn(`Choose your module ${icon('arrow')}`,'advanced','small')}</div></article></section><section class="method-strip" aria-label="Ways to practise">${[['pen','Make every stroke count','Watch the character take shape. Then try it yourself.'],['mic','Find your voice','Listen, record and build confidence with each attempt.'],['keyboard','Connect sound to meaning','Practise pinyin and the tones that make a difference.']].map(([i,t,b])=>`<div class="method"><span>${icon(i)}</span><div><h3>${t}</h3><p>${b}</p></div></div>`).join('')}</section>${!S.user?`<p class="small muted">Browse the lessons, then register and verify your email to start practising.</p>`:''}`;}
function available(id){return [...S.lessons.values()].filter(l=>l.moduleId===id&&l.published).length;}
function moduleSelect(id='module-select'){return `<select id="${id}" aria-label="Teaching module">${modules.map(m=>`<option value="${m.id}" ${m.id===S.module?'selected':''}>${m.name} · ${m.level}</option>`).join('')}</select>`;}
function weeks(admin=false){return `<div class="weeklist" aria-label="Teaching weeks">${Array.from({length:12},(_,i)=>{const n=i+1,l=S.lessons.get(lessonId(S.module,n));return `<button class="weekbutton ${n===S.week?'active':''}" data-action="week" data-week="${n}" ${!admin&&!l?.published?'disabled':''} ${n===S.week?'aria-current="true"':''}><span>Week ${String(n).padStart(2,'0')}</span><small>${l?.published?'Available':admin?'Draft':'Coming later'}</small></button>`;}).join('')}</div>`;}
function moduleView(){const m=modules.find(m=>m.id===S.module),l=S.lessons.get(lessonId(S.module,S.week));return `${btn(`${icon('back')} All modules`,'home','text')}<div class="page-head"><div><div class="eyebrow">${e(m.level)} · YOUR LEARNING PATH</div><h1>${e(m.name)}</h1><p>Pick a week, revisit a word, and make it your own.</p></div><span class="pill">12 teaching weeks</span></div><div class="module-layout"><aside class="sidebar"><label>My module${moduleSelect()}</label>${weeks()}</aside><section class="content-panel">${l?`${l.sample?'<span class="pill warm">Sample lesson · For lecturer review</span>':'<span class="pill">Ready to practise</span>'}<h2>${e(l.title)}</h2><p>${e(l.intro)}</p><div class="activity-buttons">${l.writing?btn(`${icon('pen')} Write characters`,'practice','primary','data-mode="writing"'):''}${l.speaking?btn(`${icon('mic')} Practise speaking`,'practice','','data-mode="speaking"'):''}${l.pinyin?btn(`${icon('keyboard')} Try pinyin`,'practice','','data-mode="pinyin"'):''}</div><div class="section-title"><h3 class="small">This week’s vocabulary</h3><span class="small muted">${l.vocabulary.length} words</span></div><div class="word-grid">${l.vocabulary.map(w=>`<div class="word-card"><span class="hanzi" lang="zh-CN">${e(w.hanzi)}</span>${l.showPinyin?`<span class="pinyin">${e(w.pinyin)}</span>`:''}${l.showMeaning?`<small>${e(w.meaning)}</small>`:''}</div>`).join('')}</div>`:`<div class="empty">${icon('book')}<h2>Something to look forward to.</h2><p>Lucy hasn’t published this week yet. Choose an available week to start practising.</p></div>`}</section></div>`;}
function practiceView(){const p=S.practice,w=p.words[p.index],l=p.lesson;return `<div class="practice-top">${btn(`${icon('back')} ${S.preview?'Back to editor':'Back to module'}`,'leave-practice','text')}<h1>${e(l.title)}</h1><span class="small muted">${p.index+1} / ${p.words.length}</span></div>${S.preview?'<div class="notice">Student preview. Practice results are not saved.</div>':''}<div class="practice-layout"><aside class="practice-info"><div class="eyebrow">Week ${String(l.week).padStart(2,'0')}</div><h2 style="margin-top:15px">A little room to improve.</h2><p>Take your time. Replay the example, explore the sounds and try as often as you like.</p><div class="progress-track"><span style="width:${(p.index+1)/p.words.length*100}%"></span></div><div class="mini-list">${icon('pen')} Write with your finger, pen or mouse.<br>${icon('mic')} Record a short, clear attempt.<br>${icon('refresh')} Repetition is part of learning.</div><p class="small">${S.preview?'Preview only · Attempts are not saved.':S.user?'Your completed attempts are saved.':'Guest practice · Sign in to save your attempts.'}</p></aside><section class="practice-panel"><div class="tabs" role="tablist" aria-label="Practice activity">${[['writing','pen','Writing'],['speaking','mic','Speaking'],['pinyin','keyboard','Pinyin']].filter(([k])=>l[k]).map(([k,i,label])=>`<button class="tab ${p.mode===k?'active':''}" role="tab" aria-selected="${p.mode===k}" data-action="mode" data-mode="${k}">${icon(i)} ${label}</button>`).join('')}</div><div class="word-heading hanzi" lang="zh-CN">${e(w.hanzi)}</div><p class="word-pinyin">${p.mode!=='pinyin'&&l.showPinyin?e(w.pinyin):''}</p><p class="word-meaning">${l.showMeaning?e(w.meaning):''}</p>${p.mode==='writing'?writingView():p.mode==='pinyin'?pinyinView():speakingView()}<div class="practice-bottom"><small>Week ${l.week} · ${e(modules.find(m=>m.id===l.moduleId).level)}</small><div class="row">${btn('Previous','previous','small',p.index===0?'disabled':'')}${btn(p.index===p.words.length-1?`Finish practice ${icon('check')}`:`Next word ${icon('arrow')}`,'next','primary small')}</div></div></section></div>`;}
function writingView(){const p=S.practice,w=p.words[p.index],chars=[...w.hanzi];return `<p class="small muted">${chars.length>1?`Character ${p.charIndex+1} of ${chars.length} · `:''}Draw in the box. Start at the orange dot and follow the arrow.<br>Lift your finger or mouse after each stroke.</p><div id="drawing" class="drawing-grid" aria-label="Character writing area. Draw from the orange dot along each guide. Use a finger, stylus or mouse. Keyboard users can choose the Pinyin tab."></div><div class="writing-key"><span class="ink-dot"></span>Your ink <span class="guide-dot"></span>Next stroke</div><div class="button-row">${btn(`${icon('play')} Watch strokes`,'animate','small','disabled')}${btn(`${icon('refresh')} Start again`,'write','primary small','disabled')}</div><div id="write-feedback" class="practice-feedback" role="status">Preparing your writing pad…</div><p id="writing-progress" class="small muted">${p.writeCount||0} of ${p.lesson.repetitions} repetitions completed${chars.length>1?' for this character':''}.</p>`;}
function pinyinView(){return `<form id="pinyin-form" class="pinyin-form"><label for="pinyin-answer">How do you write its pinyin?</label><input id="pinyin-answer" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="e.g. nǐ hǎo or ni3 hao3" required maxlength="120"><div class="tone-keys" aria-label="Insert tone marks">${['ā','á','ǎ','à','ē','é','ě','è','ī','í','ǐ','ì','ō','ó','ǒ','ò','ū','ú','ǔ','ù','ǖ','ǘ','ǚ','ǜ'].map(t=>`<button type="button" data-action="tone" data-tone="${t}">${t}</button>`).join('')}</div><button class="btn primary wide" type="submit">Check my answer</button></form><div id="pinyin-feedback" class="practice-feedback" role="status">Use tone marks or numbers 1–4. For neutral tones, omit the number or use 5.</div><p class="small muted">You can also use your device’s Chinese pinyin keyboard to type characters.</p>`;}
function speakingView(){if(!canPractise())return `<div class="voice-signin"><span class="auth-emblem" aria-hidden="true">声</span><h3>Your voice. Your progress.</h3><p>Register, verify your email and sign in to record your pronunciation and request feedback.</p><div class="button-row">${btn('Register','register','primary')}${btn('Sign in','sign-in')}</div><p class="small muted">Verify your email to unlock AI speech feedback.</p></div>`;return `${btn(`${icon('volume')} Listen to the word`,'listen','small')}${!S.practice.speechResult?'<div id="model-audio-output"></div>':''}<button id="record-button" class="record-orb" data-action="record" aria-label="Start recording">${icon('mic')}</button><p id="record-status" class="small muted" role="status">Tap to record · Up to 20 seconds</p><div id="recording-output">${S.practice.recordingUrl&&!S.practice.speechResult?`<audio class="audio-player" controls src="${e(S.practice.recordingUrl)}" aria-label="Your recorded pronunciation"></audio>`:''}</div><div class="button-row">${btn('Get AI feedback','speech-feedback','primary',`id="feedback-button" ${!S.practice.recordingUrl||S.practice.recording||!S.settings.backendReady||!['openai','azure'].includes(S.settings.speechProvider)?'disabled':''}`)}</div><p class="small muted">Recording stays on this device. Requesting feedback sends it to ${S.settings.speechProvider==='azure'?'Microsoft Azure':'OpenAI'} for processing.<br>${['openai','azure'].includes(S.settings.speechProvider)?'AI feedback is available to all registered users with a verified email.':'Your lecturer has not enabled AI feedback yet. Recording and playback work now.'}</p><div id="speech-result" aria-live="polite">${S.practice.speechResult?speechFeedbackView(S.practice.words[S.practice.index],S.practice.speechResult,S.practice.recordingUrl):''}</div>`;}
function strokeGuide(index){
 const target=document.querySelector('#drawing');if(!target)return;
 target.querySelector('.stroke-guide')?.remove();
 const median=strokeData?.medians?.[index];if(!median)return;
 const t=HanziWriter.getScalingTransform(writerSize,writerSize,22);
 const points=median.map(([x,y])=>[t.x+x*t.scale,writerSize-t.y-y*t.scale]);
 const [x,y]=points[0];
 target.insertAdjacentHTML('beforeend',`<svg class="stroke-guide" viewBox="0 0 ${writerSize} ${writerSize}" aria-hidden="true"><defs><marker id="stroke-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10Z" fill="#b55c3e"/></marker></defs><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#b55c3e" stroke-width="3" stroke-dasharray="4 5" stroke-linecap="round" marker-end="url(#stroke-arrow)"/><circle cx="${x}" cy="${y}" r="8" fill="#b55c3e" stroke="#fffef9" stroke-width="2"/></svg>`);
}
async function setupWriter(){
 const p=S.practice,w=p.words[p.index],generation=++drawGeneration;writer?.cancelQuiz();strokeData=null;
 const target=document.querySelector('#drawing');if(!target)return;
 try{
  writerSize=target.clientWidth;
  const current=HanziWriter.create(target,[...w.hanzi][p.charIndex],{width:writerSize,height:writerSize,padding:22,strokeColor:'#234e3d',radicalColor:'#234e3d',outlineColor:'#d5ddce',drawingColor:'#254d78',drawingWidth:12/HanziWriter.getScalingTransform(writerSize,writerSize,22).scale,drawingFadeDuration:900,highlightColor:'#ba6a32',highlightCompleteColor:'#487448',showCharacter:false,showOutline:true,strokeAnimationSpeed:1,delayBetweenStrokes:350,charDataLoader:(char,onLoad,onError)=>{fetch('/chinese/characters/'+encodeURIComponent(char)+'.json').then(r=>r.ok?r.json():fetch('https://cdn.jsdelivr.net/npm/hanzi-writer-data@2.0.1/'+encodeURIComponent(char)+'.json').then(x=>{if(!x.ok)throw Error('No stroke data');return x.json();})).then(data=>{if(generation===drawGeneration){strokeData=data;onLoad(data);}}).catch(onError);}});
  writer=current;
  target.querySelector('svg').setAttribute('viewBox',`0 0 ${writerSize} ${writerSize}`);
  await current.getCharacterData();
  if(generation!==drawGeneration)return;
  document.querySelectorAll('[data-action="animate"],[data-action="write"]').forEach(b=>b.disabled=false);
  quiz();
 }catch{if(generation===drawGeneration){document.querySelector('#write-feedback').textContent='Stroke data could not load. Reopen Writing to retry, or choose another activity.';}}
}
function quiz(){
 const p=S.practice;if(!writer||!strokeData||p?.mode!=='writing')return;
 const generation=++drawGeneration,total=strokeData.medians.length;
 const feedback=document.querySelector('#write-feedback');
 feedback.textContent=`Ready · Stroke 1 of ${total}. Start at the orange dot and follow the arrow.`;
 strokeGuide(0);
 writer.quiz({leniency:1.5,showHintAfterMisses:1,highlightOnComplete:true,
  onMistake:d=>{if(generation===drawGeneration)feedback.textContent=`Try stroke ${d.strokeNum+1} again. ${d.isBackwards?'Start at the dot and draw towards the arrow.':'Follow the orange guide, then lift your finger or mouse.'}`;},
  onCorrectStroke:d=>{if(generation!==drawGeneration)return;strokeGuide(d.strokeNum+1);if(d.strokesRemaining)feedback.textContent=`Good · Stroke ${d.strokeNum+1} accepted. Now draw stroke ${d.strokeNum+2} of ${total}.`;},
  onComplete:async d=>{
   if(generation!==drawGeneration)return;p.writeCount=(p.writeCount||0)+1;
   const w=p.words[p.index],chars=[...w.hanzi];strokeGuide(total);
   feedback.textContent=`Character completed · ${d.totalMistakes||0} stroke retries. ${p.writeCount<p.lesson.repetitions?'Choose Start again for another go.':'Ready for the next word, or Start again to keep practising.'}`;
   document.querySelector('#writing-progress').textContent=`${p.writeCount} of ${p.lesson.repetitions} repetitions completed.`;
   await saveAttempt('writing',true,d.totalMistakes||0,chars[p.charIndex]);
   if(generation!==drawGeneration)return;
   if(p.writeCount>=p.lesson.repetitions&&p.charIndex<chars.length-1){p.charIndex++;p.writeCount=0;toast('Good practice. Move to the next character.');render();}
  }
 });
}
async function saveAttempt(kind,correct,mistakes=0,hanzi){if(!canPractise()||S.preview)return;const p=S.practice;if(!p)return;try{const data={uid:S.user.uid,moduleId:p.lesson.moduleId,lessonId:lessonId(p.lesson.moduleId,p.lesson.week),hanzi:hanzi||p.words[p.index].hanzi,kind,correct,mistakes:Math.min(10000,Math.max(0,Math.round(mistakes))),createdAt:F.serverTimestamp()};await F.addDoc(F.collection(F.db,'attempts'),data);S.attempts.push(data);}catch{toast('Your attempt could not be saved. Please check your connection.');}}
function loginView(){return `<div class="login-layout"><div class="login-intro"><span class="green-label">THE TEACHING SPACE</span><h1>Your classroom.<br>Your way.</h1><p>Choose the words. Shape each week.<br>Give your students a little more room to practise.</p><div class="login-art" aria-hidden="true"><span>学</span><small>Learn. Try. Grow.</small></div><p class="small">Register with Google or email. Kostas appoints teaching administrators.</p></div><section class="login-card">${S.user?`<h2>You're signed in.</h2><p class="small muted">${e(S.user.email)}<br>Kostas can appoint you as an administrator from People & practice.</p>${btn('Back to student practice','student','primary')}${btn('Edit my name','edit-profile','text')}${btn('Sign out','logout','text')}`:authView(S.authMode,S.settings.sharedLoginEnabled)}</section></div>`;}
function adminView(){return `<div class="page-head"><div><div class="eyebrow">TEACHING SPACE</div><h1>Make room for progress.</h1><p>Small, purposeful activities. Your teaching, week by week.</p></div><a class="btn small" href="/chinese/">Student view ${icon('arrow')}</a></div><div class="admin-layout"><nav class="admin-nav" aria-label="Admin navigation">${[['curriculum','book','Curriculum'],['people','users','People & practice'],['settings','settings','Settings']].map(([k,i,t])=>`<a href="#${k}" data-action="admin-tab" data-tab="${k}" class="${S.adminTab===k?'active':''}">${icon(i)} ${t}</a>`).join('')}</nav><section class="admin-main">${S.practice?practiceView():S.adminTab==='curriculum'?editorView():S.adminTab==='people'?peopleView():settingsView()}</section></div>`;}
function editorView(){const d=S.draft||makeLesson(S.module,S.week),published=S.lessons.has(lessonId(S.module,S.week));return `<div class="admin-toolbar">${moduleSelect()}<span class="pill ${published?'':'neutral'}">${published?'Published lesson available':'Not visible to students'}</span></div><div class="admin-curriculum"><aside class="admin-weeks">${weeks(true)}</aside><form id="lesson-form" class="editor"><div class="form-section"><div class="row" style="margin-bottom:20px"><span class="eyebrow grow">WEEK ${String(S.week).padStart(2,'0')}</span><span id="draft-state" class="pill neutral">${S.dirty?'Unsaved changes':'Draft editor'}</span></div><div class="form-stack"><label>Week title<input name="title" maxlength="100" value="${e(d.title)}" required></label><label>A short introduction<textarea name="intro" maxlength="2000">${e(d.intro)}</textarea></label></div></div><div class="form-section"><h3>How students practise</h3><div class="form-grid">${[['writing','Character writing'],['speaking','Speaking & recording'],['pinyin','Pinyin practice'],['showPinyin','Show pinyin hints'],['showMeaning','Show English meaning'],['randomize','Shuffle vocabulary order']].map(([k,t])=>`<label class="check"><input name="${k}" type="checkbox" ${d[k]?'checked':''}>${t}</label>`).join('')}<label>Writing repetitions<input name="repetitions" type="number" min="1" max="10" value="${d.repetitions}"></label><label class="check"><input name="sample" type="checkbox" ${d.sample?'checked':''}>Label this as a sample lesson</label></div></div><div class="form-section"><div class="row"><h3 class="grow">This week’s vocabulary</h3>${btn(`${icon('plus')} Add word`,'add-word','small','type="button"')}</div><p>Use characters and words your class has learned. Add a short pronunciation tip if helpful.</p><div id="vocabulary-rows">${d.vocabulary.map(vocabRow).join('')}</div></div><div class="editor-actions"><button type="submit" class="btn primary">Save draft</button>${btn('Publish lesson','publish','','type="button"')}${btn('Preview lesson','preview','','type="button"')}${published?btn('Unpublish lesson','unpublish','danger-outline','type="button"'):''}</div><p class="small muted">Saving a draft does not change the lesson students see. Publish when it is ready.</p></form></div>`;}
function vocabRow(w,i){return `<div class="vocab-row" data-index="${i}"><div class="row-title">WORD ${i+1}</div>${btn('Remove','remove-word','text small remove',`type="button" data-index="${i}" aria-label="Remove word ${i+1}"`)}<div class="form-grid"><label>Characters<input data-field="hanzi" value="${e(w.hanzi)}" maxlength="12" required lang="zh-CN"></label><label>Pinyin<input data-field="pinyin" value="${e(w.pinyin)}" maxlength="120" required></label><label>English meaning<input data-field="meaning" value="${e(w.meaning)}" maxlength="200" required></label></div><label class="hint-row">Pronunciation tip<input data-field="hint" value="${e(w.hint)}" maxlength="500"></label></div>`;}
function readDraft(){const form=document.querySelector('#lesson-form');if(!form)return S.draft;const fd=new FormData(form),d={...S.draft,moduleId:S.module,week:S.week,title:fd.get('title'),intro:fd.get('intro'),repetitions:Number(fd.get('repetitions')),published:false,vocabulary:[...form.querySelectorAll('.vocab-row')].map((row,i)=>{const w={id:`word-${i+1}`};for(const input of row.querySelectorAll('[data-field]'))w[input.dataset.field]=input.value.trim();return w;})};for(const k of ['writing','speaking','pinyin','showPinyin','showMeaning','randomize','sample'])d[k]=fd.has(k);return d;}
async function loadDraft(){const id=lessonId(S.module,S.week);try{const snap=await F.getDoc(F.doc(F.db,'drafts',id));S.draft=snap.exists()?snap.data():S.lessons.get(id)||makeLesson(S.module,S.week);}catch{S.draft=S.lessons.get(id)||makeLesson(S.module,S.week);}S.draft=structuredClone(S.draft);S.dirty=false;}
function peopleRows(){const q=S.peopleSearch.toLocaleLowerCase();return directoryRows(S.members.filter(u=>[u.name,u.firstName,u.lastName,u.email].some(v=>String(v||'').toLocaleLowerCase().includes(q))),{owner:S.owner,self:S.user.uid,modules,attempts:S.attempts});}
function peopleView(){return `<div class="content-panel people-panel"><div class="row"><div class="grow"><span class="eyebrow">YOUR CLASSROOM</span><h2>People & practice</h2></div>${btn('Refresh','refresh-people','small')}</div><p>Every registered account appears here. Email verification unlocks practice automatically.</p><div class="people-toolbar"><label>Find a person<input id="people-search" type="search" placeholder="Search by name or email" value="${e(S.peopleSearch)}"></label><span class="small muted" id="people-count">${S.members.length} accounts loaded${S.nextPeoplePage?' · More available':''}</span></div><div class="table-wrap"><table class="people-table"><thead><tr><th>Person</th><th>Account</th><th>Joined & activity</th><th>Actions</th></tr></thead><tbody id="people-rows">${peopleRows()}</tbody></table></div>${S.nextPeoplePage?btn('Load more users','more-people','wide'):''}<p class="small muted">Practice counts cover the latest 200 attempts. Messages are private to each learner and the teaching team.</p>${recentPracticeView()}</div>`;}
function recentPracticeView(){return S.attempts.length?`<details class="practice-history"><summary>Recent practice · latest 30 attempts</summary><div class="table-wrap"><table><thead><tr><th>Learner</th><th>Word</th><th>Activity</th><th>Result</th></tr></thead><tbody>${S.attempts.slice(0,30).map(a=>`<tr><td>${e(S.members.find(u=>u.id===a.uid)?.name||'Learner')}</td><td class="hanzi">${e(a.hanzi)}</td><td>${e(a.kind)}</td><td>${a.correct?'Completed':'Practising'}${a.kind==='writing'?` · ${e(a.mistakes)} stroke retries`:''}</td></tr>`).join('')}</tbody></table></div></details>`:'';}
function mailSettingsView(){return S.owner?`<section class="content-panel"><span class="pill">${S.settings.mailEnabled?'Email notifications on':'Email not connected or switched off'}</span><h2>Message emails</h2><p>Send notifications from <strong>kstouras@gmail.com</strong> when an admin writes to a learner. Emails link to the private conversation; they do not contain the message.</p><form id="mail-form" class="form-stack"><label>Gmail app password<input type="password" name="password" autocomplete="new-password" required minlength="16" maxlength="32" placeholder="16-character app password"></label><p class="auth-error" role="alert" hidden></p><button type="submit" class="btn primary">Connect Gmail & enable emails</button></form><p class="small muted">Create an app password for Chinese Practice in <a href="https://myaccount.google.com/apppasswords" target="_blank" rel="noopener">your Google account</a>. Google may ask you to enable 2-Step Verification first. Use an app password, not your normal password. It is stored securely on the server and is never shown again.</p>${S.settings.mailConfigured?btn(S.settings.mailEnabled?'Pause notification emails':'Enable notification emails','toggle-mail','small',`data-enabled="${!S.settings.mailEnabled}"`):''}</section>`:'';}
async function followAccountLink(){
 const route=location.hash;if(!['#messages','#account'].includes(route)||S.openedAccountRoute===route)return;
 S.openedAccountRoute=route;
 if(!S.user){authModal();return;}if(route==='#account'){accountModal();return;}
 if(!canPractise()){verificationModal();return;}await openMessages();
}
function settingsView(){return `<div class="settings-grid">${mailSettingsView()}<section class="content-panel"><span class="pill">Server-side storage</span><h2>Speech connection</h2><p>Use OpenAI for recognised-word feedback, or Azure Speech for pronunciation scores. No AI key is sent to students.</p><form id="provider-form" class="form-stack"><label>Service<select name="provider" id="provider-select"><option value="openai">OpenAI · Speech recognition</option><option value="azure">Azure Speech · Pronunciation assessment</option></select></label><label>API key<input name="key" type="password" autocomplete="new-password" required minlength="16" maxlength="500" placeholder="Paste the service’s API key"></label><label id="azure-resource-label" hidden>Azure Speech resource name<input name="resource" placeholder="e.g. my-chinese-speech" maxlength="63"></label><button class="btn primary" type="submit">Save and use service</button></form><p class="small muted">Keys are write-only here, stored in Google Secret Manager. Replace a key by saving a new one.</p></section><section class="content-panel"><h2>Feedback controls</h2><p>Connected services can be switched off at any time. Recording and playback remain available.</p><label>Active speech service<select id="active-provider"><option value="off" ${!S.settings.speechProvider||S.settings.speechProvider==='off'?'selected':''}>Off · Recording and playback only</option><option value="openai" ${S.settings.speechProvider==='openai'?'selected':''} ${!S.settings.openaiConfigured?'disabled':''}>OpenAI ${S.settings.openaiConfigured?'· Connected':'· No key saved'}</option><option value="azure" ${S.settings.speechProvider==='azure'?'selected':''} ${!S.settings.azureConfigured?'disabled':''}>Azure Speech ${S.settings.azureConfigured?'· Connected':'· No key saved'}</option></select></label><p class="small muted">Prototype limits: 40 AI requests per learner per day, 300 across the site. New server-generated pronunciation examples share this limit; replaying a cached example does not. Each recording is capped at 20 seconds.</p><div class="notice">OpenAI transcription is not a Mandarin tone score. Azure scores also need lecturer calibration before any assessed use.</div></section>${S.owner?`<section class="content-panel"><h2>Shared teacher login</h2><p>Username: <strong>teacher</strong>. Set a password to enable the shared administrator account. Google sign-in remains available.</p><form id="shared-form" class="form-stack"><label>New shared password<input type="password" name="password" minlength="14" maxlength="128" required autocomplete="new-password"></label><label>Repeat password<input type="password" name="confirm" minlength="14" maxlength="128" required autocomplete="new-password"></label><button class="btn" type="submit">Set shared password</button></form><p class="small muted">Use at least 14 characters. Share it privately with appointed teachers.</p></section>`:''}<section class="content-panel"><h2>Made for this first step</h2><p>Three cohorts, two learning pathways and 12 weeks per module. Lucy controls the vocabulary, activity types, hints and publication.</p><p>Reading generation, live classroom sessions and graded assessments will be designed together in later iterations.</p><a class="btn small" href="/chinese/#privacy">Privacy & practice data ${icon('arrow')}</a></section></div>`;}
function privacyView(){return `<article class="content-panel privacy">${btn(`${icon('back')} Back to learning`,'home','text')}<h1>Privacy & practice data</h1><p>This is a SATLE teaching prototype, developed for Lucy Liu’s Chinese classes. Sample content is for review and practice.</p><h2>Your account and practice</h2><p>Registration stores your first and last names, email, selected module and practice attempts in the project’s Firebase database in Europe. Appointed administrators can view those records to support teaching. Guests can browse modules; practice activities require a verified account.</p><h2>Your voice</h2><p>Recordings are held temporarily in this browser and discarded when you leave the activity. If you choose “Get AI feedback”, the recording is sent through the project’s backend to the speech provider named on that screen (OpenAI or Microsoft Azure). The project does not store the audio. The feedback and transcript are saved for teaching review. Provider processing and retention follow that provider’s account terms.</p><p>Pronunciation examples use a Mandarin voice on your device when available. Otherwise, the lesson word and pinyin are sent to OpenAI to create an AI-generated example. These example recordings are cached for reuse; they contain lesson vocabulary, not your voice.</p><h2>Learning feedback</h2><p>Writing checks use Hanzi Writer’s stroke matching. OpenAI feedback reports recognised words, not measured tones. Azure pronunciation scores are automated estimates. All results are practice feedback, not assessed grades.</p><h2>Your choices</h2><p>A verified account is required to practise. You can use writing and pinyin without recording your voice. Open your account menu to read and reply to private messages, edit your name or delete your account. Deletion removes your sign-in, profile, practice history, feedback and messages; it cannot be undone. A minimal deletion marker without your name or email prevents old sessions from restoring the account. Messages are stored privately for you and the appointed teaching admins. When notification emails are enabled, your verified email address receives a short notice through Gmail with a link to read and reply. The message contents stay on this website. You can turn off these emails in your account menu. Before a student pilot, the teaching team should confirm the university’s participant information and retention arrangements.</p><h2>Credits</h2><p>Character animation and stroke checks use <a href="https://hanziwriter.org/" target="_blank" rel="noopener">Hanzi Writer</a> (MIT) and character data from Make Me a Hanzi (Arphic Public License). The character-data licence is included with the website.</p></article>`;}
async function loadPublic(){try{const [lessons,settings]=await Promise.all([F.getDocs(F.query(F.collection(F.db,'lessons'),F.where('published','==',true))),F.getDoc(F.doc(F.db,'settings','public'))]);S.lessons=new Map(lessons.docs.map(d=>[d.id,d.data()]));S.settings=settings.data()||{};S.error='';S.loaded=true;}catch{S.error='We couldn’t load the classroom. Check your connection and try again.';}}
async function register(){if(!S.user||S.user.uid==='shared-teacher')return;await F.setDoc(F.doc(F.db,'users',S.user.uid),{name:(S.profile?.name||S.user.displayName||'Learner').slice(0,120),email:S.user.email,moduleId:S.module,updatedAt:F.serverTimestamp()},{merge:true});}
async function loadPeople(more=false){const [page,attempts]=await Promise.all([F.api({action:'listUsers',...(more&&S.nextPeoplePage?{pageToken:S.nextPeoplePage}:{})}),more?null:F.getDocs(F.query(F.collection(F.db,'attempts'),F.orderBy('createdAt','desc'),F.limit(200)))]);S.members=more?[...S.members,...page.users.filter(u=>!S.members.some(x=>x.id===u.id))]:page.users;S.nextPeoplePage=page.nextPageToken;S.admins=new Set(S.members.filter(u=>u.admin).map(u=>u.id));if(attempts)S.attempts=attempts.docs.map(d=>d.data());S.rosterLoaded=true;}
async function openMessages(uid=S.user?.uid,older=false){
 if(!S.user){authModal();return;}if(!canPractise()){verificationModal();return;}
 const teacher=S.admin&&uid!==S.user.uid,user=teacher?S.members.find(u=>u.id===uid):{id:S.user.uid,name:S.user.displayName,email:S.user.email};
 if(!user)throw Error('Refresh the directory and select this person again.');
 const before=older?S.thread?.items[0]?.seq:undefined,result=await F.api({action:'getMessages',uid,...(before?{before}:{})});
 const items=older?[...result.items,...S.thread.items]:result.items;
 S.thread={user,teacher,...result,items};modal(messageView({...S.thread,mailEnabled:S.settings.mailEnabled}));
 dialog.classList.add('message-modal');
 if(!older){const list=dialog.querySelector('.message-list');list.scrollTop=list.scrollHeight;}
 const last=items.at(-1)?.seq||0;await F.api({action:'readMessages',uid,seq:last});
 if(teacher){user.needsReply=false;const rows=document.querySelector('#people-rows');if(rows)rows.innerHTML=peopleRows();}
}
function deleteModal(uid){const self=uid===S.user.uid,user=self?{id:uid,name:S.user.displayName,email:S.user.email}:S.members.find(u=>u.id===uid);if(!user)throw Error('Refresh the directory and select this person again.');modal(deletionView(user,{self,google:S.user.providerData.some(p=>p.providerId==='google.com')}));}
async function submitConversation(form){
 const button=form.querySelector('[type=submit]'),error=form.querySelector('.auth-error');button.disabled=true;error.hidden=true;
 try{const fd=new FormData(form);if(form.id==='message-form'){
  form.dataset.requestId||=crypto.randomUUID();await F.api({action:'sendMessage',uid:form.dataset.uid,body:fd.get('body'),requestId:form.dataset.requestId});await openMessages(form.dataset.uid);toast('Message sent in Chinese Practice.');
 }else{
  if(fd.get('confirmation')!=='DELETE')throw Error('Type DELETE to confirm.');
  await F.confirmIdentity(fd.get('password'));await F.api({action:'deleteAccount',uid:form.dataset.uid,confirmation:'DELETE'});
  const self=form.dataset.uid===S.user.uid;dialog.close();if(self){resetVoice();S.practice=null;await F.signOut(F.auth);}else{await loadPeople();render();}
  toast(self?'Your account deletion has started. You are signed out.':'Account deletion started. The user can no longer use the app.');
 }
 }catch(err){if(form.isConnected){error.textContent=message(err);error.hidden=false;}else toast(message(err));}
 finally{if(button.isConnected)button.disabled=false;}
}
async function chooseModule(id){S.module=id;S.week=[...S.lessons.values()].find(l=>l.moduleId===id)?.week||1;if(adminPage){await loadDraft();render();}else{location.hash=`module=${id}&week=${S.week}`;render();}if(S.user)run(register);}
function leave(){drawGeneration++;writer?.cancelQuiz();resetVoice();S.practice=null;S.preview=false;render();}
function startPractice(mode,preview=false){if(!canPractise()){S.user?verificationModal():authModal('register');return;}if(!canPractise()){verificationModal();return;}const lesson=preview?readDraft():S.lessons.get(lessonId(S.module,S.week));if(!lesson?.vocabulary.length){toast('Add vocabulary before starting this lesson.');return;}if(!lesson[mode]){toast('This activity is not enabled for this week.');return;}S.preview=preview;S.practice={lesson,mode,index:0,charIndex:0,writeCount:0,words:lesson.randomize?shuffled(lesson.vocabulary):[...lesson.vocabulary],recording:false};render();window.scrollTo(0,0);}
function parseHash(){if(adminPage){const tab=location.hash.slice(1);if(['curriculum','people','settings'].includes(tab))S.adminTab=tab;}else if(location.hash.startsWith('#module=')){const q=new URLSearchParams(location.hash.slice(1));if(modules.some(m=>m.id===q.get('module')))S.module=q.get('module');const w=Number(q.get('week'));S.week=w>=1&&w<=12?w:1;}}
function navigateGuard(action){if(!S.dirty){action();return;}modal(`<h2>Keep your changes?</h2><p>This week has unsaved changes. Save the draft first, or discard the changes to continue.</p><div class="row">${btn('Keep editing','close-dialog','primary')}${btn('Discard changes','discard-draft')}</div>`);pendingNavigation=action;}
let pendingNavigation=null;
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(b.tagName==='A'||b.closest('form'))event.preventDefault();run(async()=>{
 switch(a){
 case 'home':leave();location.hash='';render();break;
 case 'reload':await loadPublic();render();break;
 case 'start':await chooseModule(S.module);break;
 case 'choose-module':dialog.close();await chooseModule(b.dataset.module);break;
 case 'advanced':modal(`<h2>Choose your module</h2><p>Your advanced pathway has two teaching groups.</p><div class="form-stack">${modules.filter(m=>m.group==='advanced').map(m=>btn(`${e(m.name)} · ${e(m.level)} ${icon('arrow')}`,'choose-module','','data-module="'+m.id+'"')).join('')}</div>`);break;
 case 'sign-in':showAuth();break;
 case 'register':showAuth('register');break;
 case 'auth-mode':showAuth(b.dataset.mode);break;
 case 'toggle-password':{const input=document.getElementById(b.getAttribute('aria-controls')),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-pressed',String(show));b.setAttribute('aria-label',show?'Hide password':'Show password');break;}
 case 'google':{const login=F.googleLogin();dialog.close();await login;break;}
 case 'edit-profile':profileModal();break;
 case 'toggle-mail':await F.api({action:'setMail',enabled:b.dataset.enabled==='true'});await loadPublic();render();toast('Email notification setting saved.');break;
 case 'my-messages':await openMessages();break;
 case 'open-messages':case 'refresh-messages':await openMessages(b.dataset.uid);break;
 case 'older-messages':await openMessages(b.dataset.uid,true);break;
 case 'delete-user':deleteModal(b.dataset.uid);break;
 case 'delete-self':deleteModal(S.user.uid);break;
 case 'more-people':await loadPeople(true);render();break;
 case 'resend-verification':await F.resendVerification();toast('Verification email sent. Check your inbox and spam folder.');break;
 case 'check-verification':{const verified=await F.refreshVerification();if(verified){dialog.close();bindInbox();S.openedAccountRoute=null;await followAccountLink();}render();toast(verified?'Email verified. Your practice is unlocked.':'Email not verified yet. Open the link in your email, then try again.');break;}
 case 'account':accountModal();break;
 case 'logout':leave();await F.signOut(F.auth);dialog.close();break;
 case 'student':location.href='/chinese/';break;
 case 'close-dialog':dialog.close();break;
 case 'privacy':dialog.close();if(adminPage)location.href='/chinese/#privacy';else{leave();location.hash='privacy';render();}break;
 case 'week':navigateGuard(async()=>{S.week=Number(b.dataset.week);if(adminPage)await loadDraft();else location.hash=`module=${S.module}&week=${S.week}`;render();});break;
 case 'practice':startPractice(b.dataset.mode);break;
 case 'leave-practice':leave();break;
 case 'mode':resetVoice();S.practice.recording=false;S.practice.mode=b.dataset.mode;render();break;
 case 'next':if(S.practice.index===S.practice.words.length-1){const isPreview=S.preview;leave();toast(isPreview?'Preview finished.':'Practice finished. Come back whenever you’re ready for another go.');}else{resetVoice();S.practice.index++;S.practice.charIndex=0;S.practice.writeCount=0;S.practice.recording=false;render();}break;
 case 'previous':resetVoice();S.practice.index=Math.max(0,S.practice.index-1);S.practice.charIndex=0;S.practice.writeCount=0;S.practice.recording=false;render();break;
 case 'animate':{const current=writer,generation=++drawGeneration;current?.cancelQuiz();document.querySelector('.stroke-guide')?.remove();document.querySelector('#write-feedback').textContent='Watch the stroke order. Your turn starts automatically afterwards.';await current?.animateCharacter();if(generation===drawGeneration)quiz();break;}
 case 'write':case 'clear-writing':quiz();break;
 case 'tone':{const input=document.querySelector('#pinyin-answer');input.setRangeText(b.dataset.tone,input.selectionStart,input.selectionEnd,'end');input.focus();break;}
 case 'listen':{if(S.practice.recording){toast('Stop recording before playing the model.');return;}if(!canPractise()){S.user?verificationModal():authModal();return;}stopPlayback();await playback.model(S.practice.words[S.practice.index].hanzi);break;}
 case 'stop-voice':stopPlayback();break;
 case 'compare-voice':{if(!canPractise()){S.user?verificationModal():authModal();return;}stopPlayback();await playback.compare(S.practice.words[S.practice.index].hanzi,document.querySelector('#feedback-recording'));break;}
 case 'record':{
  if(!canPractise()){S.user?verificationModal():authModal('register');return;}
  if(S.practice.recording){audio.stopRecording();return;}
  resetVoice();const current=S.practice,wordIndex=current.index,take=current.speechTake;
  document.querySelector('#recording-output').textContent='';document.querySelector('#speech-result').textContent='';if(!document.querySelector('#model-audio-output')){const slot=document.createElement('div');slot.id='model-audio-output';document.querySelector('#record-button').before(slot);}document.querySelector('#model-audio-output').textContent='';document.querySelector('#feedback-button').disabled=true;
  try{const started=await audio.startRecording(({url})=>{if(!currentSpeech(current,wordIndex,take))return;current.recording=false;current.recordingUrl=url;const recordButton=document.querySelector('#record-button');if(!recordButton)return;recordButton.classList.remove('recording');recordButton.setAttribute('aria-label','Record again');document.querySelector('#record-status').textContent='Recorded. Get feedback to compare the model, your voice and the practice guide.';document.querySelector('#recording-output').innerHTML=`<audio class="audio-player" controls src="${e(url)}" aria-label="Your recorded pronunciation"></audio>`;document.querySelector('#feedback-button').disabled=!S.settings.backendReady||!['openai','azure'].includes(S.settings.speechProvider);});if(!started||!currentSpeech(current,wordIndex,take))return;current.recording=true;const recordButton=document.querySelector('#record-button');recordButton.classList.add('recording');recordButton.setAttribute('aria-label','Stop recording');document.querySelector('#record-status').textContent='Recording… Tap again to stop. Stops automatically after 20 seconds.';}catch(err){throw Error(err.name==='NotAllowedError'?'Microphone access was denied. Allow it in your browser settings, then try again.':message(err));}break;}
 case 'speech-feedback':{
  if(!S.settings.backendReady||!['openai','azure'].includes(S.settings.speechProvider)){toast('Your lecturer has not enabled AI feedback yet.');break;}
  if(S.preview){toast('AI feedback uses published lessons. Publish this lesson to test the service.');break;}if(!canPractise()){S.user?verificationModal():authModal();break;}
  const p=S.practice,w=p.words[p.index],index=p.index,take=p.speechTake,request=p.feedbackRequest=(p.feedbackRequest||0)+1;
  if(!p.recordingUrl||p.recording){toast('Record your voice first.');break;}
  stopPlayback();p.speechResult=null;document.querySelector('#speech-result').textContent='Listening to your recording…';
  try{const encoded=await audio.wavBase64();if(!currentSpeech(p,index,take,request))return;const result=await F.api({action:'speech',lessonId:lessonId(p.lesson.moduleId,p.lesson.week),wordId:w.id,audio:encoded});if(!currentSpeech(p,index,take,request))return;p.speechResult=result;document.querySelector('#recording-output').textContent='';document.querySelector('#model-audio-output')?.remove();document.querySelector('#speech-result').innerHTML=speechFeedbackView(w,result,p.recordingUrl);document.querySelector('#speech-result').scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});await playback.replay(document.querySelector('#feedback-recording'));if(currentSpeech(p,index,take,request))await saveAttempt('speaking',true);}catch(err){if(!currentSpeech(p,index,take,request))return;document.querySelector('#speech-result').textContent=message(err);throw err;}break;}
 case 'admin-tab':navigateGuard(async()=>{S.adminTab=b.dataset.tab;location.hash=S.adminTab;if(S.adminTab==='people')await loadPeople();render();});break;
 case 'add-word':S.draft=readDraft();if(S.draft.vocabulary.length>=80)throw Error('Use up to 80 words in each week.');S.draft.vocabulary.push({hanzi:'',pinyin:'',meaning:'',hint:''});S.dirty=true;render();document.querySelector('.vocab-row:last-child input')?.focus();break;
 case 'remove-word':S.draft=readDraft();S.draft.vocabulary.splice(Number(b.dataset.index),1);S.dirty=true;render();break;
 case 'publish':await saveLesson(true);break;
 case 'unpublish':modal(`<h2>Unpublish this week?</h2><p>Students will no longer be able to open this week. Your draft will be kept.</p><div class="row">${btn('Keep published','close-dialog')}${btn('Unpublish lesson','confirm-unpublish','danger')}</div>`);break;
 case 'confirm-unpublish':await F.api({action:'saveLesson',lesson:readDraft(),unpublish:true});dialog.close();await loadPublic();S.dirty=false;render();toast('Week unpublished. Your draft is kept.');break;
 case 'preview':S.draft=readDraft();startPractice(['writing','speaking','pinyin'].find(k=>S.draft[k])||'writing',true);break;
 case 'discard-draft':S.dirty=false;dialog.close();pendingNavigation?.();pendingNavigation=null;break;
 case 'refresh-people':await loadPeople();render();break;
 case 'admin-role':await F.api({action:'setAdmin',uid:b.dataset.uid,enabled:b.dataset.enabled==='true'});await loadPeople();render();toast('Administrator access updated.');break;
 }
 },b);});
async function saveLesson(publish=false){const form=document.querySelector('#lesson-form');if(!form.reportValidity())return;const draft=readDraft();draft.published=publish;await F.api({action:'saveLesson',lesson:draft,publish});S.draft=draft;S.dirty=false;await loadPublic();render();toast(publish?'Published. Students can now open this week.':'Draft saved. The student lesson is unchanged.');}
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='mail-form'){submitMail(form);return;}if(['message-form','delete-account-form'].includes(form.id)){submitConversation(form);return;}if(['auth-form','profile-form'].includes(form.id)){submitAccount(form);return;}run(async()=>{
 if(form.id==='login-form'){const fd=new FormData(form);await F.passwordLogin(fd.get('username'),fd.get('password'));form.reset();}
 if(form.id==='lesson-form')await saveLesson(false);
 if(form.id==='pinyin-form'){const p=S.practice,answer=checkPinyin(form.querySelector('input').value,p.words[p.index].pinyin),feedback=document.querySelector('#pinyin-feedback');feedback.textContent=answer==='correct'?'That’s right. The sounds and tones match.':answer==='tones'?`The sounds match. Check the tones: ${p.words[p.index].pinyin}.`:`Try again. The pinyin is ${p.words[p.index].pinyin}.`;await saveAttempt('pinyin',answer==='correct',answer==='correct'?0:1);}
 if(form.id==='provider-form'){const fd=new FormData(form);await F.api({action:'saveProvider',provider:fd.get('provider'),key:fd.get('key'),resource:fd.get('resource')});form.reset();await loadPublic();render();toast('Speech service saved securely.');}
 if(form.id==='shared-form'){const fd=new FormData(form);if(fd.get('password')!==fd.get('confirm'))throw Error('The passwords do not match.');await F.api({action:'sharedLogin',password:fd.get('password')});form.reset();await loadPublic();render();toast('Shared login enabled. Username: teacher.');}
 },form.querySelector('[type=submit]'));});

async function submitAccount(form){
 const button=form.querySelector('[type=submit]'),error=form.querySelector('.auth-error'),success=form.querySelector('.auth-success'),fd=new FormData(form),mode=form.dataset.mode;
 button.disabled=true;form.setAttribute('aria-busy','true');error.hidden=true;if(success)success.hidden=true;
 try{
  if(form.id==='profile-form'){S.profile={...S.profile,...await F.saveNames(fd.get('firstName'),fd.get('lastName'),S.module)};dialog.close();render();toast('Your name is saved.');S.openedAccountRoute=null;await followAccountLink();}
  else if(mode==='reset'){try{await F.resetPassword(fd.get('email'));}catch(err){if(!String(err.code).includes('user-not-found'))throw err;}success.textContent='If this email has an account, a reset link is on its way. Check your inbox and spam folder.';success.hidden=false;}
  else if(mode==='register'){
   if(!String(fd.get('firstName')).trim()||!String(fd.get('lastName')).trim())throw Error('Enter your first and last names.');
   const result=await F.registerEmail({email:fd.get('email'),password:fd.get('password'),firstName:fd.get('firstName'),lastName:fd.get('lastName'),moduleId:S.module});
   if(form.isConnected)dialog.close();toast(result.verificationSent?'Account created. Check your email to verify it.':'Account created. Use Resend email to request your verification link.');
  }else {await F.emailLogin(fd.get('email'),fd.get('password'));if(form.isConnected)dialog.close();}
 }catch(err){if(form.isConnected){error.textContent=authError(err);error.hidden=false;}else toast(authError(err));}
 finally{button.disabled=false;form.removeAttribute('aria-busy');}
}

document.addEventListener('input',event=>{if(event.target.id==='people-search'){S.peopleSearch=event.target.value;document.querySelector('#people-rows').innerHTML=peopleRows();}if(event.target.closest('#lesson-form')){S.dirty=true;const el=document.querySelector('#draft-state');if(el)el.textContent='Unsaved changes';}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='email-notifications'){const enabled=el.checked;run(async()=>{try{await F.setDoc(F.doc(F.db,'users',S.user.uid),{emailNotifications:enabled,updatedAt:F.serverTimestamp()},{merge:true});S.profile={...S.profile,emailNotifications:enabled};toast(enabled?'Message emails enabled.':'Message emails turned off.');}catch(err){el.checked=!enabled;throw err;}},el);}if(el.id==='module-select'){const id=el.value;navigateGuard(()=>run(()=>chooseModule(id)));}if(el.id==='provider-select'){document.querySelector('#azure-resource-label').hidden=el.value!=='azure';document.querySelector('[name=resource]').required=el.value==='azure';}if(el.id==='active-provider')run(async()=>{await F.api({action:'setProvider',provider:el.value});await loadPublic();render();toast('Active speech service updated.');});});
window.addEventListener('beforeunload',event=>{if(S.dirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',()=>{S.openedAccountRoute=null;parseHash();if(!S.practice)render();run(followAccountLink);});
document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;if(!playback.isPlaying(event.target))playback.stop();document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause();});},true);
window.addEventListener('pagehide',()=>{resetVoice();modelUrls.forEach(url=>URL.revokeObjectURL(url));modelUrls.clear();});
parseHash();render();
loadPublic().then(render);
F.onAuthStateChanged(F.auth,async user=>{
 S.openedAccountRoute=null;stopInbox?.();stopInbox=null;S.inbox={};S.thread=null;const generation=++authGeneration;S.user=user;S.profile=null;S.admin=false;S.owner=false;S.rosterLoaded=false;S.attempts=[];S.members=[];S.admins=new Set();
 if(user){try{await F.waitForRegistration();if(generation!==authGeneration)return;const token=await user.getIdTokenResult();if(generation!==authGeneration)return;S.owner=token.claims.email==='kstouras@gmail.com'&&token.claims.email_verified===true&&token.signInProvider==='google.com';const role=await F.getDoc(F.doc(F.db,'admins',user.uid));if(generation!==authGeneration)return;S.admin=S.owner||((token.claims.email_verified===true||user.uid==='shared-teacher')&&role.exists());const profile=await F.getDoc(F.doc(F.db,'users',user.uid));S.profile=profile.exists()?profile.data():null;if(profile.exists()&&modules.some(m=>m.id===profile.data().moduleId)&&!location.hash.startsWith('#module='))S.module=profile.data().moduleId;await register();if(adminPage&&S.admin){await loadDraft();if(S.adminTab==='people')await loadPeople();}}catch(error){toast('Signed in, but account details could not load: '+message(error));}}
 if(generation===authGeneration){bindInbox();render();if(user&&user.uid!=='shared-teacher'&&(!S.profile?.firstName||!S.profile?.lastName))profileModal();else await run(followAccountLink);}
});
if('speechSynthesis'in window)speechSynthesis.getVoices();

async function submitMail(form){const button=form.querySelector('[type=submit]'),error=form.querySelector('.auth-error');button.disabled=true;error.hidden=true;try{await F.api({action:'saveMail',password:new FormData(form).get('password')});form.reset();await loadPublic();render();toast('Gmail connected. New admin messages will send email notifications.');}catch(err){error.textContent=message(err);error.hidden=false;}finally{if(button.isConnected)button.disabled=false;}}
